using System;using System.IO;using System.Linq;using System.Drawing;using System.Collections.Generic;using System.Windows.Forms;using Musikbox;
class StudioDialogs59Tests {
 static int n;static void Check(bool ok,string text){if(!ok)throw new Exception(text);n++;Console.WriteLine("PASS "+text);}static IEnumerable<Control> All(Control c){yield return c;foreach(Control x in c.Controls)foreach(var y in All(x))yield return y;}static void Pump(){for(int i=0;i<4;i++){Application.DoEvents();System.Threading.Thread.Sleep(15);}}
 [STAThread]static void Main(){Application.EnableVisualStyles();var song=new Song{Artist="Interpret",Title="Titel",Source="missing.mp3"};using(var settings=new SettingsView(true,true))using(var tags=new TagEditorView(new List<Song>{song},"Test"))using(var designer=new CoverDesignerView(CoverDesign.Default(),"Test","Test"))using(var backup=new BackupRecoveryView(new List<ProjectBackupEntry>()))using(var search=new CoverSearchView("Interpret","Titel",false))using(var file=new AppOpenFileDialog{InitialDirectory=Path.GetFullPath("verify"),Filter="MP3|*.mp3"}){
  foreach(var form in new ModernForm[]{settings,tags,designer,backup,search,file}){form.Show();form.Location=new Point(10,10);Pump();Check(form.BackColor==ModernTheme.Background,"Dunkler Dialog: "+form.GetType().Name);foreach(var combo in All(form).OfType<ComboBox>())Check(combo is StudioComboBox&&combo.DrawMode==DrawMode.OwnerDrawFixed&&combo.BackColor==ModernTheme.Silver,"Dunkles Dropdown: "+form.GetType().Name);foreach(var box in All(form).OfType<CheckBox>())Check(box.FlatStyle==FlatStyle.Flat&&!box.UseVisualStyleBackColor,"Studio-Checkbox: "+form.GetType().Name);using(var image=new Bitmap(form.ClientSize.Width,form.ClientSize.Height)){using(var graphics=Graphics.FromImage(image))graphics.CopyFromScreen(form.PointToScreen(Point.Empty),Point.Empty,image.Size);image.Save(Path.GetFullPath("verify/dialog59-"+form.GetType().Name+".png"));}form.Hide();}
  Check(file.Entries is StudioListView&&file.Entries.OwnerDraw,"Dateiauswahl zeichnet Spalten und Zeilen dunkel");Check(backup.Items is StudioListView&&backup.Items.OwnerDraw,"Sicherungsliste zeichnet Spalten und Zeilen dunkel");Check(All(settings).OfType<StudioTabControl>().Any(),"Einstellungsregister ohne helle native Tabflächen");
 }
 using(var form=new ModernForm{ClientSize=new Size(500,250)}){var number=new StudioNumericUpDown{Value=1,Left=10,Top=10};var progress=new StudioProgressBar{Value=50,Left=10,Top=60,Width=400};form.Controls.Add(number);form.Controls.Add(progress);form.Show();Pump();number.UpButton();Check(number.Value==2,"Gestaltete Nummerneingabe erhält Aufwärtsfunktion");number.DownButton();Check(number.Value==1,"Gestaltete Nummerneingabe erhält Abwärtsfunktion");progress.Value=75;Check(progress.Value==75,"Violette Fortschrittsanzeige übernimmt Werte");form.Close();}
 Console.WriteLine("BESTANDEN "+n+" Dialog-/Controlprüfungen unter Mono/Xvfb; keine native Windows-Abnahme.");
 }
}
